import{_ as a,C as e,c as i,o,a0 as t,b as n,w as r,a as l,G as s,a1 as d}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Campamento de entrenamiento: Guía de fin de semana","description":"","frontmatter":{},"headers":[],"relativePath":"es/training-camp.md","filePath":"es/training-camp.md"}');const u=a({name:"es/training-camp.md"},[["render",function(a,c,u,p,m,g){const h=e("Mermaid");return o(),i("div",null,[c[2]||(c[2]=t('<h1 id="campamento-de-entrenamiento-guia-de-fin-de-semana" tabindex="-1">Campamento de entrenamiento: Guía de fin de semana <a class="header-anchor" href="#campamento-de-entrenamiento-guia-de-fin-de-semana" aria-label="Permalink to &quot;Campamento de entrenamiento: Guía de fin de semana&quot;">​</a></h1><h2 id="como-realizar-un-campamento-de-entrenamiento-de-fin-de-semana-para-10-20-jugadores" tabindex="-1">Cómo realizar un campamento de entrenamiento de fin de semana para 10-20 jugadores <a class="header-anchor" href="#como-realizar-un-campamento-de-entrenamiento-de-fin-de-semana-para-10-20-jugadores" aria-label="Permalink to &quot;Cómo realizar un campamento de entrenamiento de fin de semana para 10-20 jugadores&quot;">​</a></h2><p>Esta guía completa te ayuda a organizar y dirigir un campamento de entrenamiento de fin de semana que combina teoría, práctica y competición. Combina el contenido de juego mental de este sitio con la aplicación práctica en la pista para lograr el máximo impacto.</p><div class="tip custom-block"><p class="custom-block-title">La filosofía del campo de entrenamiento</p><p><strong>La teoría sin práctica es solo información. La práctica sin teoría es solo repetición. La competencia sin reflexión es solo juego.</strong> Este fin de semana integra las tres para un aprendizaje transformador.</p></div>',4)),(o(),n(d,null,{default:r(()=>[s(h,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:r(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[3]||(c[3]=t('<h2 id="planificacion-previa-al-campamento" tabindex="-1">Planificación previa al campamento <a class="header-anchor" href="#planificacion-previa-al-campamento" aria-label="Permalink to &quot;Planificación previa al campamento&quot;">​</a></h2><h3 id="tamano-y-estructura-del-grupo" tabindex="-1">Tamaño y estructura del grupo <a class="header-anchor" href="#tamano-y-estructura-del-grupo" aria-label="Permalink to &quot;Tamaño y estructura del grupo&quot;">​</a></h3><p><strong>Óptimo:</strong> 10-20 jugadores</p><ul><li><strong>Campamento pequeño (10-12):</strong> Intercambio más íntimo y profundo</li><li><strong>Campamento grande (16-20):</strong> Perspectivas más diversas, requiere subgrupos</li></ul><p><strong>Estructura del equipo:</strong> -Dividirse en equipos de 3-4 para practicar y competir.</p><ul><li>Mezcla niveles de habilidad y estilos de juego.</li><li>Rotar equipos durante el fin de semana.</li></ul><h3 id="requisitos-de-personal" tabindex="-1">Requisitos de personal <a class="header-anchor" href="#requisitos-de-personal" aria-label="Permalink to &quot;Requisitos de personal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rol</th><th>Responsabilidades</th><th>Cantidad</th></tr></thead><tbody><tr><td><strong>Coordinador de Desempeño Mental</strong></td><td>Facilitar sesiones teóricas, dinámicas de grupo</td><td>1</td></tr><tr><td><strong>Entrenador técnico</strong></td><td>Supervisar la práctica, brindar retroalimentación</td><td>1-2</td></tr><tr><td><strong>Director de competición</strong></td><td>Organizar el torneo, gestionar la logística</td><td>1</td></tr><tr><td><strong>Personal de apoyo</strong></td><td>Comidas, instalación, administración</td><td>1-2</td></tr></tbody></table><h3 id="requisitos-de-ubicacion" tabindex="-1">Requisitos de ubicación <a class="header-anchor" href="#requisitos-de-ubicacion" aria-label="Permalink to &quot;Requisitos de ubicación&quot;">​</a></h3><p>::: Necesidades de instalaciones de información <strong>Pista:</strong></p><ul><li>Múltiples terrenos (mínimo 3-4 pistas)</li><li>Diferentes superficies si es posible (grava, arena, dura)</li><li>Iluminación para el juego nocturno</li></ul><p><strong>Espacio interior:</strong></p><ul><li>Sala para 20 personas en círculo (sesiones teóricas)</li><li>Separado de la pista</li><li>Pizarra/proyector</li><li>Asientos cómodos</li></ul><p><strong>Alojamiento:</strong></p><ul><li>En el sitio o cerca (a poca distancia)</li><li>Las habitaciones compartidas fomentan la unión.</li><li>Espacio tranquilo para la reflexión</li></ul><p><strong>Abastecimiento:</strong></p><ul><li>Comidas centradas en la nutrición (ver <a href="./food">Guía de alimentos</a>)</li><li>Evitar los bajones de azúcar</li><li>Estaciones de hidratación :::</li></ul><h3 id="lista-de-verificacion-de-materiales" tabindex="-1">Lista de verificación de materiales <a class="header-anchor" href="#lista-de-verificacion-de-materiales" aria-label="Permalink to &quot;Lista de verificación de materiales&quot;">​</a></h3><details class="details custom-block"><summary>Lista completa de materiales</summary><p><strong>Sesiones teóricas:</strong></p><ul><li>[ ] Sillas para círculo (sin mesas)</li><li>[ ] Petanca y cochonnet para el centro</li><li>[ ] Rotafolios y marcadores</li><li>[ ] Notas adhesivas</li><li>[ ] Hojas de trabajo (Manual de usuario, Crítico interno, etc.)</li><li>[ ] Papel y bolígrafos</li><li>[ ] Proyector (para contenido del sitio web)</li></ul><p><strong>Sesiones de práctica:</strong></p><ul><li>[ ] Cinta métrica</li><li>[ ] Conos/marcadores para ejercicios</li><li>[ ] Cámara de vídeo/trípode</li><li>[ ] Portapapeles y papel (seguimiento)</li><li>[ ] Silbar</li></ul><p><strong>Competencia:</strong></p><ul><li>[ ] Hojas de puntuación</li><li>[ ] Cuadro del torneo</li><li>[ ] Premios/reconocimientos</li><li>[ ] Botiquín de primeros auxilios</li></ul><p><strong>Logística:</strong></p><ul><li>[ ] Etiquetas de nombre</li><li>[ ] Lista de participantes con contactos</li><li>[ ] Información de contacto de emergencia</li><li>[ ] Botellas de agua</li><li>[ ] Protector solar</li><li>[ ] Pañuelos (¡para trabajo emocional!)</li></ul></details><h2 id="horario-de-fin-de-semana" tabindex="-1">Horario de fin de semana <a class="header-anchor" href="#horario-de-fin-de-semana" aria-label="Permalink to &quot;Horario de fin de semana&quot;">​</a></h2><h3 id="viernes-por-la-noche-3-horas" tabindex="-1">Viernes por la noche (3 horas) <a class="header-anchor" href="#viernes-por-la-noche-3-horas" aria-label="Permalink to &quot;Viernes por la noche (3 horas)&quot;">​</a></h3><p><strong>18:00-18:30 - Llegada y bienvenida</strong></p><ul><li>Registrarse</li><li>Asignación de habitaciones</li><li>Resumen del fin de semana</li></ul><p><strong>18:30-19:30 - Cena</strong></p><ul><li>Comida centrada en la nutrición</li><li>Presentaciones informales</li></ul><p><strong>19:30-22:30 - Sesión teórica: Fundamentos</strong></p><p>Utilice la <a href="./workshop">Guía del taller</a> para una facilitación detallada:</p><ol><li><strong>Reglas básicas (15 min)</strong> - Establecer seguridad psicológica</li><li><strong>Matriz de registro (20 min)</strong> - Evaluar la energía del grupo</li><li><strong>El Iceberg (30 min)</strong> - Explora tus pensamientos internos</li><li><strong>Manual del usuario (45 min)</strong> - Fomentar la comprensión del equipo</li><li><strong>Miedo en un sombrero (45 min)</strong> - Romper el aislamiento</li><li><strong>Check-Out (15 min)</strong> - Cierra el círculo</li></ol><p><strong>22:30 - Tiempo libre</strong></p><ul><li>Socialización informal</li><li>Descanso y reflexión</li></ul>',30)),(o(),n(d,null,{default:r(()=>[s(h,{id:"mermaid-432",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:r(()=>[...c[1]||(c[1]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=t('<h3 id="sabado-dia-completo-teoria-practica" tabindex="-1">Sábado (Día completo - Teoría + Práctica) <a class="header-anchor" href="#sabado-dia-completo-teoria-practica" aria-label="Permalink to &quot;Sábado (Día completo - Teoría + Práctica)&quot;">​</a></h3><p><strong>08:00-09:00 - Desayuno y Mindfulness</strong></p><ul><li>Desayuno tranquilo</li><li>Meditación guiada opcional de 15 minutos</li><li>Establecer intenciones para el día</li></ul><p><strong>09:00-10:30 - Sesión teórica: Conectando el contenido con la experiencia</strong></p><p>Elige entre 3 y 4 temas del sitio web de la Academia y explora el juego interior:</p><p><strong>Temas de ejemplo:</strong></p><ol><li><p><strong><a href="./educación/nutrición/">Nutrición</a></strong> (20 min)</p><ul><li>&quot;¿Cómo cambia tu elección de alimentos bajo presión?&quot; -¿Comes lo que tu cuerpo necesita o lo que tu ansiedad quiere?</li><li>Práctica: Planificar la nutrición el día de la competición</li></ul></li><li><p><strong><a href="./educacion/fuerza-mental/">Fuerza mental</a></strong> (25 min) -¿Cuál es tu relación con el fracaso?</p><ul><li>&quot;¿Cómo te hablas a ti mismo después de un fallo?&quot;</li><li>Actividad: Reformular al crítico interno en entrenador interno</li></ul></li><li><p><strong>[Atención plena](./educación/atención plena/)</strong> (25 min)</p><ul><li>&quot;¿A dónde va tu mente durante la pausa antes de lanzar?&quot;</li><li>&quot;¿Qué te saca del momento presente?&quot;</li><li>Práctica: escaneo corporal de 5 minutos</li></ul></li><li><p><strong><a href="./educación/tácticas/">Tácticas</a></strong> (20 min)</p><ul><li>&quot;¿Tu elección de tiro se basa en la estrategia o en el miedo?&quot;</li><li>&quot;¿Cuándo jugar a lo seguro y cuándo tomar riesgos?&quot;</li><li>Discutir: Perfiles de riesgo en el grupo</li></ul></li></ol><p><strong>10:30-10:45 - Descanso</strong></p><p><strong>10:45-12:30 - Integración en pista: ejercicios con enfoque mental</strong></p><p><strong>Ejercicio 1: Apunta tu tiro (30 min)</strong></p><p>De la <a href="./taller">Guía del taller</a> - Practica la posesión de la intención y la duda:</p><ol><li>Anunciar el objetivo: &quot;Estoy disparando el hierro&quot;</li><li>Confianza en el estado: &quot;Soy un 7 sobre 10&quot;</li><li>Nombra el pensamiento interno: &quot;Mi voz interior me preocupa el efecto retroceso&quot;.</li><li>Ejecutar el tiro</li><li>Reflexiona: &quot;¿Qué pasó? ¿Qué aprendiste?&quot;</li></ol><p><strong>Ejercicio 2: Interferencia cognitiva (30 min)</strong></p><p>Prueba si la técnica se ha vuelto automática:</p><ul><li>El coordinador hace preguntas complejas mientras el jugador dispara.</li><li>&quot;Nombra 5 capitales&quot; o &quot;Contad hacia atrás desde 100 de 7 en 7&quot;</li><li>Éxito = la técnica es implícita, no se procesa conscientemente</li></ul><p><strong>Ejercicio 3: Práctica del manual del usuario (30 min)</strong></p><p>Aplicar los Manuales de Usuario del viernes:</p><ul><li>Jugar en equipos de 3</li><li>Después de cada disparo, los compañeros de equipo responden según el Manual del usuario</li><li>&quot;Marc necesita silencio después de un fallo&quot; - el equipo lo honra</li><li>Debrief: &quot;¿Cómo te sentiste al ser comprendido?&quot;</li></ul><p><strong>12:30-14:00 - Almuerzo y descanso</strong></p><ul><li>Comida centrada en la nutrición</li><li>Momento tranquilo para la reflexión</li><li>Opcional: Check-in individual con coordinador</li></ul><p><strong>14:00-17:00 - Sesión práctica: Adaptación del terreno</strong></p><p><strong>Objetivo:</strong> Desarrollar adaptabilidad y flexibilidad mental.</p><p><strong>Configuración:</strong></p><ul><li>Gira a través de 3-4 terrenos/pistas diferentes</li><li>45 minutos por terreno</li><li>Centrarse en la adaptación mental, no sólo en la técnica.</li></ul><p><strong>Estructura de rotación:</strong></p><table tabindex="0"><thead><tr><th>Terreno</th><th>Enfoque mental</th><th>Práctica</th></tr></thead><tbody><tr><td><strong>Terreno 1: Blando/Arena</strong></td><td>Aceptación de la incertidumbre</td><td>&quot;La donnée - aceptar lo que es&quot;</td></tr><tr><td><strong>Terreno 2: Duro/Grava</strong></td><td>Precisión bajo presión</td><td>&quot;Confía en tu técnica&quot;</td></tr><tr><td><strong>Terreno 3: Desigual</strong></td><td>Regulación emocional</td><td>&quot;Mantén la calma cuando es injusto&quot;</td></tr><tr><td><strong>Terreno 4: Competición</strong></td><td>Acceso al estado de flujo</td><td>&quot;Encuentra la zona&quot;</td></tr></tbody></table><p><strong>Facilitación:</strong></p><ul><li>El entrenador técnico proporciona retroalimentación sobre la técnica.</li><li>MPC pregunta: &quot;¿Qué está pasando en tu mente ahora mismo?&quot;</li><li>Diario de jugadores entre rotaciones</li></ul><p><strong>17:00-18:00 - Descanso y reflexión</strong></p><ul><li>Diario individual -¿Qué aprendiste sobre ti hoy?</li><li>&quot;¿Qué cosa harás diferente mañana?&quot;</li></ul><p><strong>18:00-19:00 - Cena</strong></p><p><strong>19:00-21:00 - Teoría de la tarde: Vulnerabilidad profunda</strong></p><p><strong>Actividad 1: Reformulando al crítico interno (45 min)</strong></p><p>Consulte la <a href="./workshop">Guía del taller</a> para ver el protocolo completo:</p><ol><li>Identifica la frase crítica exacta</li><li>Reformular como Coach Interno</li><li>Práctica de socios</li></ol><p><strong>Actividad 2: Preparación para la competición (45 min)</strong></p><p>Mañana es día de competición. Prepárense mentalmente:</p><ol><li><p><strong>Visualización (15 min)</strong></p><ul><li>Cierra los ojos</li><li>Imagina la toma perfecta</li><li>Siente la confianza</li><li>Observa la calma</li></ul></li><li><p><strong>Protocolos de equipo (20 min)</strong></p><ul><li>Crear señales de apoyo</li><li>&quot;Necesito un reinicio&quot; = toca la petanca</li><li>&quot;Necesito ánimo&quot; = chocar los puños</li><li>&quot;Necesito espacio&quot; = dar un paso atrás</li></ul></li><li><p><strong>Establecer intenciones (10 min)</strong></p><ul><li>&quot;Mañana me centraré en...&quot;</li><li>&quot;Mi objetivo no es ganar, sino...&quot;</li><li>&quot;Voy a practicar...&quot;</li></ul></li></ol><p><strong>Salida (30 min)</strong></p><ul><li>Comparte un miedo sobre el mañana</li><li>Comparte una intención</li><li>Apoyo grupal</li></ul><p><strong>21:00 - Tiempo libre</strong></p><ul><li>A la cama temprano (¡mañana hay competición!)</li><li>Reflexión tranquila</li></ul><h3 id="domingo-dia-de-la-competicion" tabindex="-1">Domingo (Día de la competición) <a class="header-anchor" href="#domingo-dia-de-la-competicion" aria-label="Permalink to &quot;Domingo (Día de la competición)&quot;">​</a></h3><p><strong>08:00-09:00 - Desayuno y preparación mental</strong></p><ul><li>Desayuno ligero (ver <a href="./educacion/nutricion/">Guía nutricional</a>)</li><li>Práctica de atención plena de 15 minutos</li><li>Grupos de equipo</li></ul><p><strong>09:00-09:30 - Reunión informativa sobre la competencia</strong></p><p><strong>Formato:</strong> Torneo todos contra todos</p><ul><li>Equipos de 3</li><li>Juega hasta 13 puntos</li><li>Todos juegan contra todos</li><li>Centrarse en el PROCESO, no en el resultado</li></ul><p><strong>El giro: Puntuación del rendimiento mental</strong></p><div class="tip custom-block"><p class="custom-block-title">Sistema de puntuación dual</p><p><strong>Tradicional:</strong> Puntos ganados <strong>Rendimiento mental:</strong> Calificado por MPC</p><p>Puntos de rendimiento mental (0-5 por juego):</p><ul><li>Herramientas del Manual de Usuario Usadas</li><li>Apoyó a sus compañeros de equipo de manera efectiva</li><li>Crítico interno gestionado</li><li>Permanecer presente (sin detenerse en tomas pasadas)</li><li>Seguridad psicológica demostrada</li></ul><p><strong>Ganador:</strong> Mejor puntuación combinada (tradicional + mental)</p></div><p><strong>09:30-13:00 - Competición matutina</strong></p><ul><li>Juegos de todos contra todos</li><li>MPC observa y califica</li><li>El entrenador técnico proporciona una breve retroalimentación entre juegos.</li><li>Pausas para hidratación y refrigerio</li></ul><p><strong>13:00-14:00 - Almuerzo</strong></p><ul><li>Centrado en la nutrición</li><li>Reflexión informal</li><li>Descansar</li></ul><p><strong>14:00-17:00 - Competición de la tarde</strong></p><ul><li>Continuar con el round-robin</li><li>Semifinales y finales</li><li>Aumento de la presión</li><li>Aplicar los aprendizajes de la mañana</li></ul><p><strong>17:00-17:30 - Premios y reconocimientos</strong></p><p><strong>Categorías:</strong></p><ul><li>Ganador tradicional</li><li>Ganador en rendimiento mental</li><li>Lo más mejorado</li><li>Mejor compañero de equipo</li><li>Premio al coraje (los más vulnerables)</li></ul><p><strong>17:30-19:00 - Sesión de reflexión final</strong></p><p><strong>Crítico:</strong> Aquí es donde se consolida el aprendizaje.</p><p><strong>Estructura:</strong></p><p><strong>1. Reflexión individual (15 min)</strong> Escribe en el diario: -¿Qué aprendiste sobre ti mismo este fin de semana? -¿Qué te sorprendió? -¿Qué harás diferente? -¿Qué te llevas a casa?</p><p><strong>2. Intercambio en grupos pequeños (30 min)</strong> Grupos de 4-5:</p><ul><li>Compartir información clave -¿Qué fue lo que más te resonó? -¿Qué fue lo más difícil? -¿Qué fue lo más valioso?</li></ul><p><strong>3. Integración grupal completa (30 min)</strong> Hacer un círculo:</p><ul><li>Cada persona comparte UNA conclusión clave</li><li>MPC valida y conecta temas -Discuta: &quot;¿Cómo aplicarás esto?&quot;</li></ul><p><strong>4. Compromisos (15 min)</strong></p><ul><li>Cada persona declara un compromiso</li><li>&quot;En mi próxima competición, voy a...&quot;</li><li>Grupo testigo y apoyo</li></ul><p><strong>5. Cierre (15 min)</strong></p><ul><li>Agradecer a los participantes por su valentía.</li><li>Recordar la confidencialidad</li><li>Intercambio de contactos</li><li>Seguimiento del plan (sesión online opcional)</li></ul><p><strong>19:00 - Cena y salida</strong></p><h2 id="consejos-de-facilitacion" tabindex="-1">Consejos de facilitación <a class="header-anchor" href="#consejos-de-facilitacion" aria-label="Permalink to &quot;Consejos de facilitación&quot;">​</a></h2><h3 id="equilibrando-la-teoria-y-la-practica" tabindex="-1">Equilibrando la teoría y la práctica <a class="header-anchor" href="#equilibrando-la-teoria-y-la-practica" aria-label="Permalink to &quot;Equilibrando la teoría y la práctica&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">No sobrecargue la teoría</p><p><strong>El error:</strong> Hablar demasiado y hacer poco</p><p><strong>El equilibrio:</strong></p><ul><li>La teoría crea conciencia</li><li>La práctica desarrolla habilidades</li><li>Integración de pruebas de competición</li><li>La reflexión consolida el aprendizaje</li></ul><p><strong>Regla general:</strong> 30% teoría, 40% práctica, 20% competencia, 10% reflexión</p></div><h3 id="gestion-de-la-dinamica-de-grupo" tabindex="-1">Gestión de la dinámica de grupo <a class="header-anchor" href="#gestion-de-la-dinamica-de-grupo" aria-label="Permalink to &quot;Gestión de la dinámica de grupo&quot;">​</a></h3><p><strong>El Alfa Competitivo:</strong></p><ul><li>Quiere ganar a toda costa</li><li>Resiste la vulnerabilidad <strong>Estrategia:</strong> Canalizar la competitividad hacia la puntuación del rendimiento mental</li></ul><p><strong>El observador silencioso:</strong> -Lo absorbe todo, no lo comparte.</p><ul><li><strong>Estrategia:</strong> Crear puntos de entrada de bajo riesgo, validar la observación como participación</li></ul><p><strong>El escéptico:</strong></p><ul><li>&quot;Esto de ser sensiblero no funciona&quot;</li><li><strong>Estrategia:</strong> Aikido verbal - alinear y pivotar (ver <a href="./taller">Guía del taller</a>)</li></ul><p><strong>El que comparte demasiado:</strong></p><ul><li>Domina la discusión</li><li><strong>Estrategia:</strong> &quot;Gracias, escuchemos a los demás&quot;</li></ul><h3 id="como-manejar-momentos-emocionales" tabindex="-1">Cómo manejar momentos emocionales <a class="header-anchor" href="#como-manejar-momentos-emocionales" aria-label="Permalink to &quot;Cómo manejar momentos emocionales&quot;">​</a></h3><p><strong>Alguien llora durante Miedo en un sombrero:</strong></p><ul><li>✅ Normalizar: “Las lágrimas son coraje, no debilidad”</li><li>✅ Ofrece pañuelos, no te apresures</li><li>✅ Pregunta: &quot;¿Qué necesitas ahora mismo?&quot;</li><li>❌ No: &quot;Está bien, no llores&quot;</li></ul><p><strong>Conflicto entre jugadores:</strong></p><ul><li>✅ Pausa y dirección</li><li>✅ &quot;¿Qué está pasando ahora mismo?&quot;</li><li>✅ Úsalo como momento de aprendizaje</li><li>❌ No: Ignorar o minimizar</li></ul><p><strong>Alguien se apaga:</strong></p><ul><li>✅ Regístrese de forma privada durante el descanso</li><li>✅ &quot;Me di cuenta de que te quedaste en silencio. ¿Qué pasa?&quot;</li><li>✅ Ofrece opciones: participa de manera diferente, tómate un descanso</li><li>❌ No: Llamar públicamente</li></ul><h2 id="seguimiento-posterior-al-campamento" tabindex="-1">Seguimiento posterior al campamento <a class="header-anchor" href="#seguimiento-posterior-al-campamento" aria-label="Permalink to &quot;Seguimiento posterior al campamento&quot;">​</a></h2><h3 id="inmediato-24-48-horas" tabindex="-1">Inmediato (24-48 horas) <a class="header-anchor" href="#inmediato-24-48-horas" aria-label="Permalink to &quot;Inmediato (24-48 horas)&quot;">​</a></h3><p><strong>Enviar a todos los participantes:</strong></p><ul><li>Mensaje de agradecimiento</li><li>Resumen de las conclusiones clave</li><li>Fotos del fin de semana</li><li>Lista de contactos (con permiso)</li><li>Enlace a recursos en el sitio web</li></ul><p><strong>Check-in individual:</strong></p><ul><li>Envía un mensaje de texto a cualquier persona que haya compartido mucho.</li><li>¿Cómo te sientes respecto al fin de semana?</li><li>Abordar cualquier vulnerabilidad residual</li></ul><h3 id="corto-plazo-2-semanas" tabindex="-1">Corto plazo (2 semanas) <a class="header-anchor" href="#corto-plazo-2-semanas" aria-label="Permalink to &quot;Corto plazo (2 semanas)&quot;">​</a></h3><p><strong>Sesión online opcional (60-90 min):</strong> -¿Cómo has aplicado los aprendizajes? ¿Qué funciona? ¿Qué supone un reto?</p><ul><li>Apoyo entre pares y resolución de problemas</li><li>Reforzar los compromisos</li></ul><h3 id="largo-plazo-1-3-meses" tabindex="-1">Largo plazo (1-3 meses) <a class="header-anchor" href="#largo-plazo-1-3-meses" aria-label="Permalink to &quot;Largo plazo (1-3 meses)&quot;">​</a></h3><p><strong>Participantes de la encuesta:</strong> -¿Qué hay de diferente en tu juego? -¿Qué herramientas sigues utilizando? -¿Qué haría que el próximo campamento fuera mejor?</p><ul><li>¿Lo recomendarías a otros?</li></ul><p><strong>Impacto en la pista:</strong></p><ul><li>Resultados de la competición</li><li>Confianza autoinformada</li><li>Dinámica de equipo</li><li>Compromiso continuo</li></ul><h2 id="adaptacion-para-diferentes-tamanos-de-grupos" tabindex="-1">Adaptación para diferentes tamaños de grupos <a class="header-anchor" href="#adaptacion-para-diferentes-tamanos-de-grupos" aria-label="Permalink to &quot;Adaptación para diferentes tamaños de grupos&quot;">​</a></h2><h3 id="campamento-pequeno-10-12-jugadores" tabindex="-1">Campamento pequeño (10-12 jugadores) <a class="header-anchor" href="#campamento-pequeno-10-12-jugadores" aria-label="Permalink to &quot;Campamento pequeño (10-12 jugadores)&quot;">​</a></h3><p><strong>Ventajas:</strong></p><ul><li>Compartir más profundamente</li><li>Más atención individualizada</li><li>Lazos más fuertes</li></ul><p><strong>Ajustes:</strong></p><ul><li>Grupo único para toda la teoría</li><li>Más tiempo por persona en actividades</li><li>Formato de competición íntima</li></ul><h3 id="campamento-grande-16-20-jugadores" tabindex="-1">Campamento grande (16-20 jugadores) <a class="header-anchor" href="#campamento-grande-16-20-jugadores" aria-label="Permalink to &quot;Campamento grande (16-20 jugadores)&quot;">​</a></h3><p><strong>Ventajas:</strong></p><ul><li>Diversas perspectivas</li><li>Mayor variedad de competencia</li><li>Economías de escala</li></ul><p><strong>Ajustes:</strong></p><ul><li>Dividirse en 2 grupos para algunas sesiones teóricas.</li><li>Se necesitan 2 MPC/facilitadores</li><li>Cuadro de torneo más grande</li><li>Rotaciones más estructuradas</li></ul><h2 id="consideraciones-presupuestarias" tabindex="-1">Consideraciones presupuestarias <a class="header-anchor" href="#consideraciones-presupuestarias" aria-label="Permalink to &quot;Consideraciones presupuestarias&quot;">​</a></h2><h3 id="ganancia" tabindex="-1">Ganancia <a class="header-anchor" href="#ganancia" aria-label="Permalink to &quot;Ganancia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artículo</th><th>Precio por Persona</th><th>20 Personas</th><th>10 Personas</th></tr></thead><tbody><tr><td><strong>Inscripción</strong></td><td>150-250 €</td><td>3.000-5.000 €</td><td>1.500-2.500 €</td></tr></tbody></table><h3 id="gastos" tabindex="-1">Gastos <a class="header-anchor" href="#gastos" aria-label="Permalink to &quot;Gastos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Categoría</th><th>Costo</th><th>Notas</th></tr></thead><tbody><tr><td><strong>Alquiler de instalaciones</strong></td><td>500-1.000 €</td><td>Tarifa de fin de semana</td></tr><tr><td><strong>Alojamiento</strong></td><td>40-60 €/persona/noche</td><td>Habitaciones compartidas</td></tr><tr><td><strong>Comidas</strong></td><td>30-40 €/persona/día</td><td>6 comidas</td></tr><tr><td><strong>Personal</strong></td><td>500-1.000 €</td><td>MPC + autocares</td></tr><tr><td><strong>Materiales</strong></td><td>100-200 €</td><td>Hojas de trabajo, materiales</td></tr><tr><td><strong>Premios</strong></td><td>100-200 €</td><td>Artículos de reconocimiento</td></tr></tbody></table><p><strong>Total por persona:</strong> 120-180 € <strong>Margen:</strong> 30-70 €/persona (o punto de equilibrio para la creación de comunidad)</p><h2 id="metricas-de-exito" tabindex="-1">Métricas de éxito <a class="header-anchor" href="#metricas-de-exito" aria-label="Permalink to &quot;Métricas de éxito&quot;">​</a></h2><h3 id="indicadores-inmediatos" tabindex="-1">Indicadores inmediatos <a class="header-anchor" href="#indicadores-inmediatos" aria-label="Permalink to &quot;Indicadores inmediatos&quot;">​</a></h3><ul><li>[ ] Puntuación de seguridad psicológica (promedio 1-10 &gt;7)</li><li>[ ] Tasa de participación (&gt;80% compartiendo activamente)</li><li>[ ] Tasa de finalización (&gt;90% estancia fin de semana completo)</li><li>[ ] Puntuación de satisfacción (promedio 1-10 &gt;8)</li></ul><h3 id="indicadores-a-largo-plazo" tabindex="-1">Indicadores a largo plazo <a class="header-anchor" href="#indicadores-a-largo-plazo" aria-label="Permalink to &quot;Indicadores a largo plazo&quot;">​</a></h3><ul><li>[ ] Cambio de comportamiento (uso de herramientas en competición)</li><li>[ ] Mejora del rendimiento (autoinformado)</li><li>[ ] Construcción de comunidad (mantenerse en contacto)</li><li>[ ] Referencias (recomendar a otros)</li></ul><h2 id="errores-comunes-que-se-deben-evitar" tabindex="-1">Errores comunes que se deben evitar <a class="header-anchor" href="#errores-comunes-que-se-deben-evitar" aria-label="Permalink to &quot;Errores comunes que se deben evitar&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Trampas</p><p><strong>1. Demasiado contenido</strong></p><ul><li>Tratando de cubrirlo todo</li><li><strong>Solución:</strong> Concéntrese en la profundidad, no en la amplitud</li></ul><p><strong>2. Saltarse la reflexión</strong></p><ul><li>Apresurándose a la siguiente actividad</li><li><strong>Solución:</strong> Tiempo de procesamiento incorporado</li></ul><p><strong>3. Ignorar la resistencia</strong></p><ul><li>Superando el escepticismo</li><li><strong>Solución:</strong> Abordarlo directamente con Aikido Verbal</li></ul><p><strong>4. Coaching técnico durante la teoría</strong></p><ul><li>Mezcla de roles</li><li><strong>Solución:</strong> Límites claros entre MPC y entrenador técnico</li></ul><p><strong>5. Sin seguimiento</strong></p><ul><li>El fin de semana termina, el aprendizaje se detiene</li><li><strong>Solución:</strong> Planificar puntos de contacto posteriores al campamento</li></ul></div><h2 id="recursos" tabindex="-1">Recursos <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;Recursos&quot;">​</a></h2><h3 id="desde-este-sitio" tabindex="-1">Desde este sitio <a class="header-anchor" href="#desde-este-sitio" aria-label="Permalink to &quot;Desde este sitio&quot;">​</a></h3><ul><li><a href="./taller">Guía del taller</a> - Protocolos detallados de facilitación</li><li><a href="./training-session">Guía de la sesión de entrenamiento</a> - Para la práctica continua</li><li><a href="./educacion/nutricion/">Nutrición</a> - Protocolos para el día de competición</li><li><a href="./educacion/fuerza-mental/">Fuerza Mental</a> - Conceptos del juego interior</li><li><a href="./educacion/mindfulness/">Mindfulness</a> - Técnicas de presencia</li><li><a href="./educación/tácticas/">Tácticas</a> - Pensamiento estratégico</li></ul><h3 id="lectura-recomendada" tabindex="-1">Lectura recomendada <a class="header-anchor" href="#lectura-recomendada" aria-label="Permalink to &quot;Lectura recomendada&quot;">​</a></h3><ul><li><em>El juego interior del tenis</em> de Timothy Gallwey</li><li><em>Mentalidad</em> de Carol Dweck</li><li><em>La organización intrépida</em> de Amy Edmondson</li></ul>',134))])}]]);export{c as __pageData,u as default};
